package com.visionerp.controller; import com.visionerp.service.AuthService; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService a){auth=a;}public record Login(@Email String email,@NotBlank String password){}@PostMapping("/login")public Map<String,String> login(@RequestBody Login r){return Map.of("token",auth.login(r.email(),r.password()));}@GetMapping("/me")public Map<String,Object> me(org.springframework.security.core.Authentication a){return Map.of("email",a.getName(),"roles",a.getAuthorities().stream().map(Object::toString).toList());}}
